+  const allowed = Object.keys(FILE_METADATA_SCHEMA.properties);
+  for (const key of Object.keys(args)) {
+    if (!allowed.includes(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+  const { path: p } = args;
+  if (typeof p !== 'string' || p.length === 0) {
+    throw new Error('path is required and must be a non-empty string');
+  }
+}
+
+function resolveWithinData(relativePath) {
+  const resolved = path.resolve(DATA_DIR, relativePath);
+  const rel = path.relative(DATA_DIR, resolved);
+  if (rel.startsWith('..') || path.isAbsolute(rel)) {
+    throw new Error('path traversal is not allowed');
+  }
+  return resolved;
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'file_metadata') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  validateArguments(args);
+  const resolved = resolveWithinData(args.path);
+  let stat;
+  try {
+    stat = fs.statSync(resolved);
+  } catch (e) {
+    throw new Error(`File not found: ${args.path}`);
+  }
+  if (!stat.isFile()) {
+    throw new Error(`Not a file: ${args.path}`);
+  }
+  const relPath = path.relative(DATA_DIR, resolved);
+  const size = stat.size;
+  const ext = path.extname(resolved).toLowerCase();
+  return {
+    content: [
+      {
+        type: 'text',
+        text: `path: ${relPath}\nsize: ${size} bytes\nextension: ${ext}`
+      }
+    ]
+  };
